         let (slots, rest) = rest.split_at_mut(layout.ring_bytes());
         let (event_slots, arena) = rest.split_at_mut(layout.event_ring_bytes());
         let frame_start = header::get_u32(header, OFF_WRITE_CURSOR);
         Self {
             header,
             slots,
             event_slots,
             arena,
