 * application's actor thread (the same model as Angular change detection and the
 * single-threaded app actor in {@code examples/pathland-web}).
 *
 * @param <T> the value type
 */
@FunctionalInterface
public interface Signal<T> {

    /** Read the current value, registering a dependency on the current context. */
    T get();
}

package com.pathland.view.signal;

import java.util.function.UnaryOperator;

/**
 * A writable signal (Angular-style {@code WritableSignal}). Setting a new value
 * that differs (per the equality comparator) propagates to dependent computed
 * signals and effects, which flush synchronously at the end of the write.
 *
 * @param <T> the value type
 */
public interface WritableSignal<T> extends Signal<T> {

    /** Replace the current value. No-op (no propagation) when equal to the current value. */
    void set(T value);

    /** Derive a new value from the current one and {@link #set} it. */
    void update(UnaryOperator<T> fn);

    /** A read-only view of this signal (write methods are not available). */
    Signal<T> asReadonly();
}

package com.pathland.view.signal;

/** Handle to a running effect; {@link #destroy()} unsubscribes it from the reactive graph. */
public interface EffectRef {

    /** Stop the effect: it will no longer re-run on dependency changes. */
    void destroy();
}

package com.pathland.view.signal;

/**
 * Options controlling an {@code effect}.
 *
 * <p>Mirrors Angular's {@code effect(fn, { allowSignalWrites, manualCleanup })}.
 *
 * @param allowSignalWrites whether the effect may write to signals. Defaults to
 *                          {@code false}: writes inside an effect throw, preventing
 *                          write/read cycles.
 * @param manualCleanup     when {@code true} the effect is not scheduled on creation
 *                          (the caller must run it); reserved for lifecycle-managed
 *                          frameworks.
 */
public record EffectOptions(boolean allowSignalWrites, boolean manualCleanup) {

    /** Default: no signal writes, effect scheduled immediately on creation. */
    public static final EffectOptions DEFAULT = new EffectOptions(false, false);

    /** An effect that may write to signals. */
    public static EffectOptions allowSignalWrites() {
        return new EffectOptions(true, false);
    }
}

package com.pathland.view.signal;

import java.util.ArrayList;
import java.util.List;

/**
 * Package-private base node of the reactive graph. Each node owns:
 *
 * <ul>
 *   <li>a monotonically increasing {@code version}, bumped only when the node's own
 *       value actually changes (equality-suppressed writes do not bump it);</li>
 *   <li>a {@code producers} list (nodes read during the last evaluation) with the
 *       producer version observed at that time, so a node can cheaply skip re-running
 *       when nothing it depends on actually changed (glitch-free + equality
 *       suppression);</li>
 *   <li>a {@code consumers} list (nodes that depend on this node), used to mark them
 *       dirty and schedule effects when this node's value changes.</li>
 * </ul>
 */
abstract class ReactiveNode {

    /** A producer edge: the producer node plus its version when this node last read it. */
    static final class ProducerEdge {
        final ReactiveNode node;
        long lastSeenVersion;

        ProducerEdge(ReactiveNode node) {
            this.node = node;
            this.lastSeenVersion = node.version;
        }
    }

    final List<ProducerEdge> producers = new ArrayList<>();
    final List<ReactiveNode> consumers = new ArrayList<>();

    /** Bumped when this node's own value changes. */
    long version;

    /** Whether this node must (re)evaluate. */
    boolean dirty = true;

    /** Whether the evaluation function has run at least once. */
    boolean firstRun = true;

    /** Whether this node may write signals during its evaluation. */
    boolean allowSignalWrites = false;

    /** Cached evaluation error (computed) / last run error (effect). */
    Throwable error;

    final String name;

    ReactiveNode(String name) {
        this.name = name;
    }

    String describe() {
        return name != null ? name : getClass().getSimpleName();
    }

    /**
     * Register a dependency from the current reactive context to {@code this}.
     * Called by {@code Signal#get()}.
     */
    final void recordDependency() {
        ReactiveNode consumer = ReactiveContext.current();
        if (consumer == null) {
            return; // plain read outside any reactive context: no dependency
        }
        int idx = consumer.indexOfProducer(this);
        if (idx < 0) {
            consumer.producers.add(new ProducerEdge(this));
            this.consumers.add(consumer);
        } else {
            // Re-read within the same evaluation: refresh the observed version.
            consumer.producers.get(idx).lastSeenVersion = version;
        }
    }

    private int indexOfProducer(ReactiveNode producer) {
        for (int i = 0; i < producers.size(); i++) {
            if (producers.get(i).node == producer) {
                return i;
            }
        }
        return -1;
    }

    /**
     * True when at least one producer's version differs from what this node last
     * observed. Used to skip re-evaluation when a dirty mark turned out not to
     * correspond to an actual value change.
     */
    final boolean depsChanged() {
        for (ProducerEdge edge : producers) {
            if (edge.node.version != edge.lastSeenVersion) {
                return true;
            }
        }
        return false;
    }

    /** Drop all producer edges (and remove this node from each producer's consumers). */
    final void resetProducers() {
        for (ProducerEdge edge : producers) {
            edge.node.consumers.remove(this);
        }
        producers.clear();
    }

    /**
     * Called after this node's own value changed: mark every (transitive) consumer
     * dirty and schedule the effects among them. Computed consumers are only flagged;
     * they re-evaluate lazily on read.
     */
    final void propagate() {
        for (ReactiveNode consumer : consumers) {
            consumer.markDirtyAndPropagate();
        }
    }

    private void markDirtyAndPropagate() {
        if (dirty) {
            return;
        }
        dirty = true;
        if (this instanceof Effect effect) {
            effect.schedule();
        }
        for (ReactiveNode consumer : consumers) {
            consumer.markDirtyAndPropagate();
        }
    }

    /** Throw this node's cached evaluation error (rethrow semantics). */
    final void rethrowError() {
        Throwable t = error;
        if (t instanceof RuntimeException re) {
            throw re;
        }
        if (t instanceof Error er) {
            throw er;
        }
        throw new EffectException("Reactive node '" + describe() + "' failed", t);
    }

    /** Guard against signal writes inside computed/effect bodies. */
    final void checkWriteAllowed() {
        ReactiveNode current = ReactiveContext.current();
        if (current == null || current.allowSignalWrites) {
            return;
        }
        throw new IllegalStateException(
                "Signal writes are not allowed inside " + current.describe()
                        + "; pass EffectOptions.allowSignalWrites() to opt out");
    }
}

package com.pathland.view.signal;

import java.util.ArrayDeque;

/**
 * The reactive evaluation context: a thread-local stack of consumers (a computed
 * being evaluated or an effect running). Signal reads register dependencies against
 * the top of this stack.
 *
 * <p>Single-threaded by contract (the app-actor model).
 */
final class ReactiveContext {

    private static final ThreadLocal<ArrayDeque<ReactiveNode>> STACK =
            ThreadLocal.withInitial(ArrayDeque::new);

    private ReactiveContext() {}

    /** The consumer currently evaluating, or {@code null} outside any reactive context. */
    static ReactiveNode current() {
        return STACK.get().peek();
    }

    /** The underlying stack (used by {@code Signals#untracked}). */
    static ArrayDeque<ReactiveNode> stack() {
        return STACK.get();
    }

    static void push(ReactiveNode node) {
        ArrayDeque<ReactiveNode> stack = STACK.get();
        if (stack.contains(node)) {
            throw new IllegalStateException(
                    "Circular signal dependency detected while evaluating '" + node.describe() + "'");
        }
        stack.push(node);
    }

    static void pop() {
        STACK.get().pop();
    }
}

package com.pathland.view.signal;

import java.util.ArrayDeque;

/**
 * Synchronous effect scheduler. Dirty effects are queued and flushed to quiescence
 * at the end of the outermost signal write — the deterministic flush model chosen
 * for SSR + WebSocket delta streaming. No async surprises: by the time {@code set}
 * returns, all effects that depend (transitively) on the write have run.
 */
final class Scheduler {

    private static final ArrayDeque<Effect> QUEUE = new ArrayDeque<>();
    private static boolean flushing = false;

    private Scheduler() {}

    static void schedule(Effect effect) {
        if (!effect.scheduled) {
            effect.scheduled = true;
            QUEUE.add(effect);
        }
        flush();
    }

    static void flush() {
        if (flushing) {
            return;
        }
        flushing = true;
        try {
            while (!QUEUE.isEmpty()) {
                Effect effect = QUEUE.poll();
                effect.scheduled = false;
                effect.runIfScheduled();
            }
        } finally {
            flushing = false;
        }
    }

    /** Drop a destroyed effect from the queue. */
    static void cancel(Effect effect) {
        QUEUE.remove(effect);
        effect.scheduled = false;
    }
}

package com.pathland.view.signal;

/**
 * Unchecked exception thrown when an {@code effect} body throws during the
 * synchronous flush, so the failure surfaces at the write that triggered it.
 */
public final class EffectException extends RuntimeException {

    public EffectException(String message, Throwable cause) {
        super(message, cause);
    }
}

package com.pathland.view.signal;

import java.util.Objects;
import java.util.function.BiPredicate;
import java.util.function.UnaryOperator;

/**
 * A writable signal backed by a reactive graph node.
 */
final class WritableSignalImpl<T> extends ReactiveNode implements WritableSignal<T> {

    private T value;
    private final BiPredicate<T, T> equal;

    WritableSignalImpl(T value, BiPredicate<T, T> equal, String name) {
        super(name);
        this.value = Objects.requireNonNull(value, "initial value");
        this.equal = equal;
    }

    @Override
    public T get() {
        recordDependency();
        return value;
    }

    @Override
    public void set(T value) {
        if (equal.test(this.value, value)) {
            return; // equality-suppressed: no propagation
        }
        checkWriteAllowed();
        this.value = Objects.requireNonNull(value, "value");
        version++;
        propagate(); // marks consumers dirty, schedules effects, flushes synchronously
    }

    @Override
    public void update(UnaryOperator<T> fn) {
        set(fn.apply(value));
    }

    @Override
    public Signal<T> asReadonly() {
        return this::get;
    }
}

package com.pathland.view.signal;

import java.util.Objects;
import java.util.function.BiPredicate;
import java.util.function.Supplier;

/**
 * A lazy, memoized derived signal (Angular-style {@code computed}).
 *
 * <p>The body runs only on first read and thereafter only when a producer's version
 * actually changed. If the recomputed value equals the cached value (per the equality
 * comparator), the version is not bumped and nothing downstream re-runs. A throw in
 * the body is cached and rethrown on subsequent reads until a producer changes.
 */
final class ComputedSignal<T> extends ReactiveNode implements Signal<T> {

    private final Supplier<T> fn;
    private final BiPredicate<T, T> equal;
    private T cachedValue;

    ComputedSignal(Supplier<T> fn, BiPredicate<T, T> equal, String name) {
        super(name);
        this.fn = Objects.requireNonNull(fn, "computed body");
        this.equal = equal;
    }

    @Override
    public T get() {
        evaluateIfDirty();
        if (error != null) {
            rethrowError(); // cached error rethrown until a producer changes
        }
        recordDependency();
        return cachedValue;
    }

    private void evaluateIfDirty() {
        if (!dirty) {
            return;
        }
        dirty = false;
        if (!firstRun && !depsChanged()) {
            return; // producers unchanged since last evaluation: nothing to recompute
        }
        firstRun = false;
        ReactiveContext.push(this);
        resetProducers();
        try {
            T next = fn.get();
            if (equal.test(cachedValue, next)) {
                // Same value: keep version, do not propagate to consumers.
                error = null;
            } else {
                cachedValue = next;
                error = null;
                version++;
                propagate();
            }
        } catch (Throwable t) {
            if (!Objects.equals(error, t)) {
                error = t;
                version++; // notify consumers so they re-run and observe the error
                propagate();
            }
        } finally {
            ReactiveContext.pop();
        }
    }
}

package com.pathland.view.signal;

import java.util.Objects;

/**
 * A reactive effect (Angular-style {@code effect}). Runs its body immediately on
 * creation, tracking the signals it reads; re-runs (synchronously, via the shared
 * {@link Scheduler}) whenever a tracked dependency's value actually changes.
 */
final class Effect extends ReactiveNode implements EffectRef {

    private final Runnable fn;
    boolean scheduled;

    Effect(Runnable fn, EffectOptions options, String name) {
        super(name);
        this.fn = Objects.requireNonNull(fn, "effect body");
        this.allowSignalWrites = options.allowSignalWrites();
        if (!options.manualCleanup()) {
            schedule();
        }
    }

    void schedule() {
        Scheduler.schedule(this);
    }

    void runIfScheduled() {
        if (!dirty) {
            return;
        }
        dirty = false;
        if (!firstRun && !depsChanged()) {
            return; // dirtied transitively, but no tracked producer actually changed
        }
        firstRun = false;
        ReactiveContext.push(this);
        resetProducers();
        try {
            fn.run();
            error = null;
        } catch (Throwable t) {
            error = t;
            throw new EffectException("Effect '" + describe() + "' threw during flush", t);
        } finally {
            ReactiveContext.pop();
        }
    }

    @Override
    public void destroy() {
        Scheduler.cancel(this);
        resetProducers();
        dirty = false;
    }
}

package com.pathland.view.signal;

import java.util.Objects;
import java.util.function.BiPredicate;
import java.util.function.Supplier;

/**
 * Factory for Angular-style reactive primitives:
 *
 * <pre>{@code
 * WritableSignal<Integer> count = Signals.signal(0);
 * Signal<String> label = Signals.computed(() -> "Count: " + count.get());
 * EffectRef e = Signals.effect(() -> emit(label.get()));
 * count.set(1); // synchronously flushes the effect
 * e.destroy();
 * int n = Signals.untracked(() -> count.get()); // no dependency recorded
 * }</pre>
 *
 * <p>Equality defaults to {@link Objects#equals}. Effects flush synchronously at the
 * end of the outermost write. Signals are single-threaded by contract.
 */
public final class Signals {

    private Signals() {}

    /** A writable signal with {@link Objects#equals} equality. */
    public static <T> WritableSignal<T> signal(T initial) {
        return new WritableSignalImpl<>(initial, Objects::equals, null);
    }

    /** A writable signal with a custom equality comparator. */
    public static <T> WritableSignal<T> signal(T initial, BiPredicate<T, T> equal) {
        return new WritableSignalImpl<>(initial, Objects.requireNonNull(equal, "equal"), null);
    }

    /** A named writable signal (names surface in dependency errors). */
    public static <T> WritableSignal<T> signal(String name, T initial) {
        return new WritableSignalImpl<>(initial, Objects::equals, name);
    }

    /** A lazy, memoized derived signal. */
    public static <T> Signal<T> computed(Supplier<T> fn) {
        return new ComputedSignal<>(Objects.requireNonNull(fn, "computed body"), Objects::equals, null);
    }

    /** A derived signal with a custom equality comparator. */
    public static <T> Signal<T> computed(Supplier<T> fn, BiPredicate<T, T> equal) {
        return new ComputedSignal<>(
                Objects.requireNonNull(fn, "computed body"), Objects.requireNonNull(equal, "equal"), null);
    }

    /** A named derived signal. */
    public static <T> Signal<T> computed(String name, Supplier<T> fn) {
        return new ComputedSignal<>(Objects.requireNonNull(fn, "computed body"), Objects::equals, name);
    }

    /** Register an effect; runs immediately, then on tracked dependency changes. */
    public static EffectRef effect(Runnable fn) {
        return effect(fn, EffectOptions.DEFAULT);
    }

    /** Register an effect with options. */
    public static EffectRef effect(Runnable fn, EffectOptions options) {
        return new Effect(
                Objects.requireNonNull(fn, "effect body"),
                Objects.requireNonNull(options, "options"),
                null);
    }

    /** A named effect. */
    public static EffectRef effect(String name, Runnable fn) {
        return new Effect(Objects.requireNonNull(fn, "effect body"), EffectOptions.DEFAULT, name);
    }

    /**
     * Read signals without recording dependencies on the enclosing context. Any
     * signals read inside {@code fn} are not tracked, so the surrounding computed or
     * effect will not re-run when they change.
     */
    public static <T> T untracked(Supplier<T> fn) {
        ArrayDeque<ReactiveNode> stack = ReactiveContext.stack();
        ArrayDeque<ReactiveNode> saved = new ArrayDeque<>(stack);
        stack.clear();
        try {
            return Objects.requireNonNull(fn, "untracked body").get();
        } finally {
            stack.addAll(saved);
        }
    }
}

