    const out = new Uint8Array(16 + 16 + 4);
    const h = new DataView(out.buffer);
    h.setUint32(0, 0x504c504c, true); h.setUint16(4, 1, true); h.setUint16(6, 1, true);
    h.setUint32(12, 1, true);
    const op = new DataView(out.buffer, 16);
    op.setUint8(0, CAT_EVENT); op.setUint8(1, CMD_POINTER_UP); op.setUint32(4, target, true);
    return out;
}

function encodeTextChanged(target, text) {
    const textBytes = new TextEncoder().encode(text);
    const out = new Uint8Array(16 + 16 + 4 + 4 + textBytes.length);
    const h = new DataView(out.buffer);
    h.setUint32(0, 0x504c504c, true); h.setUint16(4, 1, true); h.setUint16(6, 1, true);
    h.setUint32(12, 1, true);
