/** Broadcast a delta frame to every connected client (call on the actor thread). */
    private void broadcast(Frame frame) {
        if (clients.isEmpty()) {
            log("broadcast skipped: no clients (frame has " + frame.opcodes().size() + " ops)");
            return;
        }
        byte[] bytes = FrameCodec.encodeFrame(frame);
        log("broadcast " + bytes.length + " bytes to " + clients.size() + " clients");
        for (WebSocketConnection client : clients) {
            try {
                client.sendBinaryAndAwait(bytes);
            } catch (RuntimeException e) {
                clients.remove(client);
                log("broadcast failed: " + e);
            }
        }
    }

