@@ -0,0 +1,32 @@
+package com.pathland.demo;
+
+import com.pathland.view.View;
+import com.pathland.view.signal.Signal;
+
+/**
+ * A view component: the count label plus its increment button.
+ *
+ * <p>The DSL's {@link View} hierarchy is sealed, so application-level components like this
+ * one compose the library's primitives rather than implementing {@code View} directly; the
+ * composed {@link #view()} renders and reacts like any other view.
+ */
+public final class CounterControls {
+
+    private final View view;
+
+    /**
+     * @param label       the reactive count label (e.g. {@code "Count: 3"})
+     * @param onIncrement the action run when the button is tapped
+     */
+    public CounterControls(Signal<String> label, Runnable onIncrement) {
+        this.view = View.hstack(
+                View.text(label),
+                View.button("Increment", onIncrement)
+        ).padding(16);
+    }
+
+    /** The composed view (the label and a button wired to {@code onIncrement}). */
+    public View view() {
+        return view;
+    }
+}
