package com.pathland.demo;

import com.pathland.view.View;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;

/**
 * A view component: the count label plus its increment button.
 *
 * <p>The component owns its {@code count} state signal, derives the {@code "Count: N"}
 * label from it, and wires the button to increment it — a self-contained, stateful
 * component. The DSL's {@link View} hierarchy is sealed, so application-level components
 * like this one compose the library's primitives rather than implementing {@code View}
 * directly; the composed {@link #view()} renders and reacts like any other view.
 */
public final class CounterControls {

    private final WritableSignal<Integer> count;
    private final View view;

    public CounterControls() {
        this.count = Signals.signal("count", 0);
        Signal<String> countLabel = Signals.computed("countLabel", () -> "Count: " + count.get());
        this.view = View.hstack(
                View.text(countLabel),
                View.button("Increment", () -> count.update(v -> v + 1))
        ).padding(16);
    }

    /** The component's count state. */
    public WritableSignal<Integer> count() {
        return count;
    }

    /** The composed view (the label and a button wired to increment {@code count}). */
    public View view() {
        return view;
    }
}

package com.pathland.demo;

import com.pathland.view.Color;
import com.pathland.view.View;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;

/**
 * The application's root view: the {@link CounterControls} component, a name text field,
 * the reactive name label, and a footer — composed from DSL primitives and components.
 * Owns the derived {@code nameLabel} computed; the counter's {@code count} state lives in
 * {@link CounterControls}, exposed via {@link #controls()}.
 */
public final class CounterView {

    private final CounterControls controls;
    private final View view;

    public CounterView(WritableSignal<String> name) {
        this.controls = new CounterControls();
        Signal<String> nameLabel = Signals.computed("nameLabel", () -> "Name: " + name.get());

        this.view = View.vstack(
                controls.view(),
                View.textField("Your name", name),
                View.text(nameLabel),
                View.text("Pathland · Quarkus · per-session · 16-byte deltas")
                        .color(Color.rgb(0x88, 0x88, 0x88))
        ).padding(24);
    }

    /** The counter controls component (owns the {@code count} signal). */
    public CounterControls controls() {
        return controls;
    }

    /** The composed root view. */
    public View view() {
        return view;
    }
}

