package com.pathland.demo;

import com.pathland.view.View;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;

/**
 * A view component: the name text field plus its reactive label.
 *
 * <p>The component owns its {@code name} state signal, binds the {@link com.pathland.view.TextField}
 * to it, and derives the {@code "Name: …"} label from it — a self-contained, stateful
 * component. The DSL's {@link View} hierarchy is sealed, so application-level components
 * compose the library's primitives rather than implementing {@code View} directly.
 */
public final class NameField {

    private final WritableSignal<String> name;
    private final View view;

    public NameField() {
        this.name = Signals.signal("name", "");
        Signal<String> nameLabel = Signals.computed("nameLabel", () -> "Name: " + name.get());
        this.view = View.vstack(
                View.textField("Your name", name),
                View.text(nameLabel)
        );
    }

    /** The component's name state. */
    public WritableSignal<String> name() {
        return name;
    }

    /** The composed view (the text field and its reactive label). */
    public View view() {
        return view;
    }
}

package com.pathland.demo;

import com.pathland.view.Color;
import com.pathland.view.View;

/**
 * The application's root view: the {@link CounterControls} component, the {@link NameField}
 * component, and a footer — composed from DSL primitives and components. Each component
 * owns its own state ({@code count} in {@link CounterControls}, {@code name} in
 * {@link NameField}), exposed via {@link #controls()} and {@link #nameField()}.
 */
public final class CounterView {

    private final CounterControls controls;
    private final NameField nameField;
    private final View view;

    public CounterView() {
        this.controls = new CounterControls();
        this.nameField = new NameField();

        this.view = View.vstack(
                controls.view(),
                nameField.view(),
                View.text("Pathland · Quarkus · per-session · 16-byte deltas")
                        .color(Color.rgb(0x88, 0x88, 0x88))
        ).padding(24);
    }

    /** The counter controls component (owns the {@code count} signal). */
    public CounterControls controls() {
        return controls;
    }

    /** The name field component (owns the {@code name} signal). */
    public NameField nameField() {
        return nameField;
    }

    /** The composed root view. */
    public View view() {
        return view;
    }
}

