```java
public void connect(Object view) {
    Class<?> c = view.getClass();
    if (noBinder.contains(c)) return;
    Method m = binders.get(c);
    if (m == null) {
        try {
            Class<?> bc = Class.forName(c.getName() + "_StateBinder");
            m = bc.getMethod("connect", c, PersistentState.class);
            binders.put(c, m);
        } catch (ClassNotFoundException e) {
            noBinder.add(c);
            return;
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("state binder for " + c + " is unusable", e);
        }
    }
    try {
        m.invoke(null, view, this);
    } catch (ReflectiveOperationException e) {
        throw new IllegalStateException("state connect failed for " + c, e);
    }
}
```

