package com.pathland.view.state;

import java.util.Optional;

/**
 * A cross-platform state store abstraction. The exact same application code runs on a
 * multi-tenant server (Redis), a desktop app (File/SQLite), a browser (LocalStorage),
 * or an embedded ESP32 (NVS Flash) by swapping the {@link StateStore} implementation —
 * component state is decoupled from the storage mechanism.
 *
 * <p>The store is untyped: {@link #load} takes the value's class for a type check and
 * {@link #save} accepts any (serializable) value, so a single store serves every
 * signal type.
 */
public interface StateStore {

    /** Load state for {@code key} (type-checked against {@code clazz}), or empty when absent. */
    <T> Optional<T> load(String key, Class<T> clazz);

    /** Persist {@code state} for {@code key}. */
    void save(String key, Object state);

    /** Remove state for {@code key}. */
    void delete(String key);
}

package com.pathland.view.state;

import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

/**
 * An in-memory {@link StateStore}. Thread-safe ({@link ConcurrentHashMap}), so server
 * apps can read state from request threads while a session actor writes it. Zero
 * dependencies; the fallback when no durable backend is configured.
 */
public final class InMemoryStateStore implements StateStore {

    private final ConcurrentMap<String, Object> states = new ConcurrentHashMap<>();

    @Override
    public <T> Optional<T> load(String key, Class<T> clazz) {
        Object value = states.get(key);
        if (value != null && clazz.isInstance(value)) {
            return Optional.of(clazz.cast(value));
        }
        return Optional.empty();
    }

    @Override
    public void save(String key, Object state) {
        states.put(key, state);
    }

    @Override
    public void delete(String key) {
        states.remove(key);
    }

    @Override
    public String toString() {
        return "InMemoryStateStore(" + states.size() + " keys)";
    }
}

package com.pathland.view.state;

/**
 * Pluggable provider of {@link StateStore}s. A platform (Quarkus, Spring Boot, a
 * desktop launcher) contributes a provider so the application layer is written once
 * against {@link StateStore} and the storage mechanism is chosen at startup.
 */
public interface StateStoreProvider {

    /** A store, optionally qualified (e.g. {@code "redis"}). */
    StateStore store(String... qualifiers);

    /** A human-readable platform name (e.g. {@code "redis"}, {@code "in-memory"}). */
    default String platform() {
        return "unknown";
    }
}

package com.pathland.view.state;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Marks a {@link State} field for automatic persistence. The {@code pathland-view-processor}
 * annotation processor generates a binder that connects the field to the session's
 * {@link PersistentState} at mount time, keyed by the field's name (scoped to the
 * declaring view class).
 *
 * <p>The field must be of type {@link State}{@code <T>} and be package-private (so the
 * generated binder, in the same package, can reach it). Example:
 *
 * <pre>{@code
 * public final class Counter implements View {
 *     @Persisted State<Integer> count = new State<>(0);
 *     ...
 * }
 * }</pre>
 */
@Retention(RetentionPolicy.SOURCE)
@Target(ElementType.FIELD)
public @interface Persisted {

    /** Optional explicit store key; defaults to the field name. */
    String value() default "";
}

package com.pathland.view.state;

import com.pathland.view.signal.WritableSignal;

import java.util.function.UnaryOperator;

/**
 * A field-holder for a persisted signal (the Java realization of a SwiftUI-style
 * {@code @State} field, wired by the {@code pathland-view-processor} annotation
 * processor). Declared as a {@code @Persisted} field in a view and populated by the
 * generated binder before the first render.
 *
 * <pre>{@code
 * @Persisted State<Integer> count = new State<>(0);
 * count.get();              // current value
 * count.update(v -> v + 1); // mutate (persisted automatically)
 * }</pre>
 *
 * @param <T> the state type
 */
public final class State<T> {

    private final T initial;
    private WritableSignal<T> signal;

    public State(T initial) {
        this.initial = initial;
    }

    /** Called by the generated binder to connect this state to the store under {@code name}. */
    public void bind(PersistentState state, String name) {
        this.signal = state.signal(name, initial);
    }

    /** The underlying signal (for {@code TextField}, {@code View.text(Signal)}, …). */
    public WritableSignal<T> signal() {
        return signal;
    }

    /** The current value. */
    public T get() {
        return signal.get();
    }

    /** Replace the value. */
    public void set(T value) {
        signal.set(value);
    }

    /** Derive a new value from the current one and set it. */
    public void update(UnaryOperator<T> fn) {
        signal.update(fn);
    }
}

package com.pathland.view.state;

import com.pathland.view.signal.EffectRef;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;

import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * A per-session handle that connects {@link State} fields to a {@link StateStore}.
 *
 * <p>{@link #signal(String, Object)} creates a signal that auto-loads its persisted value
 * as the initial value and auto-saves on every change, keyed {@code "name:scope"}. Signals
 * are memoized by name, so repeat calls return the same instance. {@link #connect(Object)}
 * wires a view's {@code @Persisted} fields (and, recursively, its nested view fields)
 * through the binder generated by {@code pathland-view-processor}.
 */
public final class PersistentState implements AutoCloseable {

    /** Generated binder methods, cached per view class. */
    private static final Map<Class<?>, Method> BINDERS = new ConcurrentHashMap<>();
    private static final Set<Class<?>> NO_BINDER = ConcurrentHashMap.newKeySet();

    private final StateStore store;
    private final String scope;
    private final Map<String, WritableSignal<?>> signals = new HashMap<>();
    private final List<EffectRef> persistEffects = new ArrayList<>();

    public PersistentState(StateStore store, String scope) {
        this.store = store;
        this.scope = scope;
    }

    /**
     * Create (or return the memoized) signal named {@code name}, auto-loading its
     * persisted value as the initial value and auto-saving on change.
     */
    @SuppressWarnings("unchecked")
    public <T> WritableSignal<T> signal(String name, T initial) {
        WritableSignal<T> existing = (WritableSignal<T>) signals.get(name);
        if (existing != null) {
            return existing;
        }
        String key = scoped(name);
        Class<T> clazz = (Class<T>) initial.getClass();
        WritableSignal<T> signal = Signals.signal(name, store.load(key, clazz).orElse(initial));
        signals.put(name, signal);
        persistEffects.add(Signals.effect(() -> {
            try {
                store.save(key, signal.get());
            } catch (RuntimeException e) {
                // Persistence is best-effort for a UI component.
            }
        }));
        return signal;
    }

    private String scoped(String name) {
        return scope == null || scope.isEmpty() ? name : name + ":" + scope;
    }

    /**
     * Wire every {@code @Persisted} field of {@code view} — and, recursively, of its
     * nested view fields — through the generated {@code <Class>_StateBinder}. Views
     * without generated binders (e.g. library primitives) are a no-op.
     */
    public void connect(Object view) {
        Class<?> type = view.getClass();
        if (NO_BINDER.contains(type)) {
            return;
        }
        Method binder = BINDERS.get(type);
        if (binder == null) {
            try {
                Class<?> binderClass = Class.forName(type.getName() + "_StateBinder");
                binder = binderClass.getMethod("connect", type, PersistentState.class);
                BINDERS.put(type, binder);
            } catch (ClassNotFoundException e) {
                NO_BINDER.add(type);
                return;
            } catch (ReflectiveOperationException e) {
                throw new IllegalStateException("state binder for " + type + " is unusable", e);
            }
        }
        try {
            binder.invoke(null, view, this);
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("state connect failed for " + type, e);
        }
    }

    @Override
    public void close() {
        for (EffectRef effect : persistEffects) {
            effect.destroy();
        }
        persistEffects.clear();
        signals.clear();
    }
}

